export type OwnerDescriptor = { "schema_version": 1; "owner_id": string; "owner_type": "research" | "run" | "project" | "core-algorithm" | "knowledge" | "report" | "data" | "tool"; "native_ref": { "path": string; "id_field"?: (string) | (null); "id_value"?: (string) | (null) }; "memory_home": string; "created_at": string; "created_by": Actor; "adapter_version": number; "aliases"?: Array<string> };
export type Operation = { "op": "put_record" | "transition_question" | "set_policy" | "decide_association" | "save_checkpoint"; "client_key"?: string; "record_id"?: string; "expected_revision"?: number; "draft": RequestDraft };
export type CommitRequest = { "schema_version": 1; "request_id": string; "actor": Actor; "owner_id": string; "expected_head": (string) | (null); "operations": Array<Operation>; "dry_run"?: boolean };
export type RecordResult = { "record_id": string; "revision": number; "content_hash": string; "client_key": (string) | (null); "status"?: "would_create" | "would_update" | "no_change" | "created" | "updated" };
export type CommitReceipt = { "request_id": string; "owner_id": string; "commit_id": (string) | (null); "generation": number; "save_status": "committed" | "no_change" | "not_committed"; "record_results": Array<RecordResult>; "index_status": "indexed" | "pending" | "failed"; "index_details": IndexDetails; "warnings": Array<string>; "error": ({ "code": string; "message": string }) | (null); "recovery_ref": (string) | (null) };
export type RequestDraft = { [key: string]: unknown };
